return [
  {
    json: {
      owner: "Jamoko112026",
    repository: "JaMoKo_Automation_OS",
   path: "01_REGISTRY/workflow_registry.md",
      ref: "main"
    }
  }
];

try {
const input = $json;

const requiredFields = [
  "owner",
  "repository",
  "path",
  "ref"
];

const missingFields = requiredFields.filter(
  (field) => !(field in input)
);

if (missingFields.length > 0) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "INPUT_INVALID",
        message: `Pflichtfelder fehlen: ${missingFields.join(", ")}`
      }
    }
  };
}

const invalidTypeFields = requiredFields.filter(
  (field) => typeof input[field] !== "string"
);

if (invalidTypeFields.length > 0) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "INPUT_INVALID",
        message: `Pflichtfelder besitzen einen ungültigen Datentyp: ${invalidTypeFields.join(", ")}`
      }
    }
  };
}

const emptyFields = requiredFields.filter(
  (field) => input[field].length === 0
);

if (emptyFields.length > 0) {
  const errorCode = emptyFields.includes("ref")
    ? "REF_MISSING"
    : "INPUT_INVALID";

  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: errorCode,
        message: `Pflichtfelder sind leer: ${emptyFields.join(", ")}`
      }
    }
  };
}

const boundaryWhitespaceFields = requiredFields.filter(
  (field) => input[field] !== input[field].trim()
);

if (boundaryWhitespaceFields.length > 0) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "INPUT_INVALID",
        message: `Pflichtfelder dürfen keine führenden oder nachgestellten Leerzeichen enthalten: ${boundaryWhitespaceFields.join(", ")}`
      }
    }
  };
}

return {
  json: {
    status: "validated",
    mode: "read-only",
    input: {
      owner: input.owner,
      repository: input.repository,
      path: input.path,
      ref: input.ref
    }
  }
};
} catch {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "GITHUB_API_ERROR",
        message: "Der Reader konnte die Eingabe nicht sicher verarbeiten."
      }
    }
  };
}

try {
const data = $json;

if (data.status === "rejected") {
  return {
    json: data
  };
}

const allowedTargets = [
  {
    owner: "Jamoko112026",
    repository: "JaMoKo_Automation_OS"
  }
];

const { owner, repository } = data.input;

const ownerAllowed = allowedTargets.some(
  (target) => target.owner === owner
);

if (!ownerAllowed) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "OWNER_NOT_ALLOWED",
        message: "Der angegebene GitHub-Owner ist nicht freigegeben."
      }
    }
  };
}

const repositoryAllowed = allowedTargets.some(
  (target) => target.repository === repository
);

if (!repositoryAllowed) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "REPOSITORY_NOT_ALLOWED",
        message: "Das angegebene Repository ist nicht freigegeben."
      }
    }
  };
}

const targetAllowed = allowedTargets.some(
  (target) =>
    target.owner === owner &&
    target.repository === repository
);

if (!targetAllowed) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "REPOSITORY_NOT_ALLOWED",
        message: "Die Kombination aus Owner und Repository ist nicht freigegeben."
      }
    }
  };
}

return {
  json: {
    ...data,
    status: "target-allowed",
    target: {
      owner,
      repository
    }
  }
};
} catch {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "GITHUB_API_ERROR",
        message: "Der Reader konnte die Zielprüfung nicht sicher abschließen."
      }
    }
  };
}

try {
const data = $json;

if (data.status === "rejected") {
  return {
    json: data
  };
}

const path = data.input?.path;

if (typeof path !== "string" || path.length === 0) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "PATH_INVALID",
        message: "Der Dateipfad fehlt oder ist ungültig."
      }
    }
  };
}

const hasControlCharacters = /[\u0000-\u001F\u007F]/.test(path);
const isAbsolute = path.startsWith("/") || /^[A-Za-z]:[\\/]/.test(path);
const hasBackslashes = path.includes("\\");
const hasEmptySegments = path.includes("//");
const segments = path.split("/");
const hasTraversalSegments = segments.some(
  (segment) => segment === "." || segment === ".."
);
const hasWhitespaceBoundary = path !== path.trim();

if (
  hasControlCharacters ||
  isAbsolute ||
  hasBackslashes ||
  hasEmptySegments ||
  hasTraversalSegments ||
  hasWhitespaceBoundary
) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "PATH_INVALID",
        message: "Der Dateipfad ist nicht als sicherer relativer Repository-Pfad zulässig."
      }
    }
  };
}

const validatedPath = path;

return {
  json: {
    ...data,
    status: "path-validated",
    input: {
      ...data.input,
      path: validatedPath
    },
    validatedPath: validatedPath
  }
};
} catch {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "GITHUB_API_ERROR",
        message: "Der Reader konnte die Pfadprüfung nicht sicher abschließen."
      }
    }
  };
}

function rejected(code, message) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: { code, message }
    }
  };
}

try {
  const response = $json;
  const request = $("05 Validate Path").item.json;

  if (response && response.error) {
    return rejected(
      "GITHUB_API_ERROR",
      "Der GitHub-Lesezugriff ist technisch fehlgeschlagen."
    );
  }

  const statusCode = Number(response?.statusCode ?? 200);
  const body = response?.body ?? response;

  if (statusCode === 401) {
    return rejected("AUTHENTICATION_FAILED", "Die GitHub-Authentifizierung ist fehlgeschlagen.");
  }
  if (statusCode === 403) {
    return rejected("ACCESS_DENIED", "Der Zugriff auf die angeforderte GitHub-Datei wurde verweigert.");
  }
  if (statusCode === 404) {
    return rejected("FILE_NOT_FOUND", "Die angeforderte Datei oder Referenz wurde nicht gefunden.");
  }
  if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) {
    return rejected("GITHUB_API_ERROR", "Die GitHub API konnte die Anfrage nicht erfolgreich verarbeiten.");
  }

  if (
    !body ||
    body.type !== "file" ||
    typeof body.path !== "string" ||
    typeof body.sha !== "string" ||
    typeof body.content !== "string" ||
    body.encoding !== "base64"
  ) {
    return rejected("READ_VALIDATION_FAILED", "Die GitHub-Antwort enthält nicht die erwarteten Dateidaten.");
  }

  if (
    body.path !== request.validatedPath ||
    !/^[a-fA-F0-9]{40}$/.test(body.sha)
  ) {
    return rejected("READ_VALIDATION_FAILED", "Pfad oder Datei-SHA der GitHub-Antwort ist ungültig.");
  }

  if (/[ \t\f\v]/.test(body.content)) {
    return rejected("CONTENT_DECODE_FAILED", "Der Dateiinhalt ist nicht strikt Base64-kodiert.");
  }

  const compactBase64 = body.content.replace(/[\r\n]/g, "");
  const validBase64 =
    compactBase64.length % 4 === 0 &&
    /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(compactBase64);

  if (!validBase64) {
    return rejected("CONTENT_DECODE_FAILED", "Der Dateiinhalt konnte nicht dekodiert werden.");
  }

  const decodedBuffer = Buffer.from(compactBase64, "base64");
  if (decodedBuffer.toString("base64") !== compactBase64) {
    return rejected("CONTENT_DECODE_FAILED", "Der Dateiinhalt konnte nicht verlustfrei aus Base64 dekodiert werden.");
  }

  const decodedContent = decodedBuffer.toString("utf8");
  if (!Buffer.from(decodedContent, "utf8").equals(decodedBuffer)) {
    return rejected("CONTENT_DECODE_FAILED", "Der Dateiinhalt ist nicht strikt und verlustfrei als UTF-8 dekodierbar.");
  }

  return {
    json: {
      status: "read",
      mode: "read-only",
      source: {
        owner: request.target.owner,
        repository: request.target.repository,
        ref: request.input.ref
      },
      file: {
        path: body.path,
        sha: body.sha,
        encoding: body.encoding,
        content: decodedContent
      }
    }
  };
} catch {
  return rejected("GITHUB_API_ERROR", "Der Reader konnte die GitHub-Antwort nicht sicher verarbeiten.");
}

const writeProtection = {
  writeRequested: false,
  writeExecuted: false,
  commitCreated: false,
  pushExecuted: false
};

const allowedErrorCodes = new Set([
  "INPUT_INVALID",
  "REF_MISSING",
  "OWNER_NOT_ALLOWED",
  "REPOSITORY_NOT_ALLOWED",
  "PATH_INVALID",
  "AUTHENTICATION_FAILED",
  "ACCESS_DENIED",
  "FILE_NOT_FOUND",
  "GITHUB_API_ERROR",
  "CONTENT_DECODE_FAILED",
  "READ_VALIDATION_FAILED"
]);

function safeError(code, message) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: allowedErrorCodes.has(code) ? code : "GITHUB_API_ERROR",
        message:
          typeof message === "string" && message.trim().length > 0
            ? message.trim()
            : "Die Anfrage wurde kontrolliert abgelehnt."
      },
      ...writeProtection
    }
  };
}

try {
  const data = $json;

  if (!data || typeof data !== "object" || Array.isArray(data)) {
    return safeError("GITHUB_API_ERROR", "Der Reader konnte kein gültiges Ergebnis erzeugen.");
  }

  if (data.status === "rejected") {
    return safeError(data.error?.code, data.error?.message);
  }

  const sourceValid =
    data.source &&
    typeof data.source === "object" &&
    !Array.isArray(data.source) &&
    typeof data.source.owner === "string" &&
    data.source.owner.length > 0 &&
    data.source.owner === data.source.owner.trim() &&
    typeof data.source.repository === "string" &&
    data.source.repository.length > 0 &&
    data.source.repository === data.source.repository.trim() &&
    typeof data.source.ref === "string" &&
    data.source.ref.length > 0 &&
    data.source.ref === data.source.ref.trim();

  const fileValid =
    data.file &&
    typeof data.file === "object" &&
    !Array.isArray(data.file) &&
    typeof data.file.path === "string" &&
    data.file.path.length > 0 &&
    data.file.path === data.file.path.trim() &&
    typeof data.file.sha === "string" &&
    /^[a-fA-F0-9]{40}$/.test(data.file.sha) &&
    data.file.encoding === "base64" &&
    typeof data.file.content === "string";

  if (
    data.status !== "read" ||
    data.mode !== "read-only" ||
    data.error !== undefined ||
    !sourceValid ||
    !fileValid
  ) {
    return safeError("READ_VALIDATION_FAILED", "Das Leseergebnis ist unvollständig oder ungültig.");
  }

  return {
    json: {
      status: "read",
      mode: "read-only",
      source: {
        owner: data.source.owner,
        repository: data.source.repository,
        ref: data.source.ref
      },
      file: {
        path: data.file.path,
        sha: data.file.sha,
        encoding: data.file.encoding,
        content: data.file.content
      },
      ...writeProtection
    }
  };
} catch {
  return safeError("GITHUB_API_ERROR", "Der Reader konnte kein sicheres Ergebnis erzeugen.");
}

const writeProtection = {
  writeRequested: false,
  writeExecuted: false,
  commitCreated: false,
  pushExecuted: false
};

const items = $input.all();
const singleEmptyPlaceholder =
  items.length === 1 &&
  items[0] &&
  items[0].json &&
  typeof items[0].json === "object" &&
  !Array.isArray(items[0].json) &&
  Object.keys(items[0].json).length === 0 &&
  (!items[0].binary || Object.keys(items[0].binary).length === 0);

if (items.length === 0 || singleEmptyPlaceholder || items.length > 1) {
  return [
    {
      json: {
        status: "rejected",
        mode: "read-only",
        error: {
          code: "INPUT_INVALID",
          message: "Der Reader benötigt exakt ein Eingangsobjekt."
        },
        ...writeProtection
      }
    }
  ];
}

return [
  {
    json: items[0].json,
    pairedItem: { item: 0 }
  }
];
